framework_component_specs.ArticleCalendarSection:
# ArticleCalendarSection

Interactive article archive calendar; not for individual article content. Implement in `app/articles/ArticleCalendarSection.tsx`. Uses React Router `Link` for pagination and receives data through props; no loader or action is required.

## Props
All props are required unless marked optional.

| Prop | Type | Description |
|---|---|---|
| title | string | Section title |
| articles | Article[] | All calendar articles |
| paginatedArticles | Article[] | Visible articles |
| currentPage | number | Current page |
| totalPages | number | Page count |
| pageSize | number | Articles per page; pagination is supplied by parent |
| paginationBasePath | string | Pagination base URL |
| id | string? | Anchor ID; defaults to `"calendar"` |
| paginationHash | string? | Pagination URL hash |
| selectedDate | Date? | Controlled selected date |
| onDateSelect | (date: Date) => void? | Date-click callback |

Dates use ISO `YYYY-MM-DD` publication days. Selection filters all articles; otherwise show `paginatedArticles`.

## Working TSX example
```tsx
"use client";

import { useState } from "react";
import { Link } from "react-router";

type Article = {
  slug: string;
  title: string;
  date: string;
  description?: string;
  image?: string;
};
type Props = {
  title: string;
  articles: Article[];
  paginatedArticles: Article[];
  currentPage: number;
  totalPages: number;
  pageSize: number;
  paginationBasePath: string;
  id?: string;
  paginationHash?: string;
  selectedDate?: Date;
  onDateSelect?: (date: Date) => void;
};
function dateKey(date: Date): string {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}
export function ArticleCalendarSection(p: Props) {
  const [month, setMonth] = useState(p.selectedDate ?? new Date());
  const [localDate, setLocalDate] = useState<Date>();
  const selected = p.selectedDate ?? localDate;
  const year = month.getFullYear();
  const index = month.getMonth();
  const count = new Date(year, index + 1, 0).getDate();
  const visible = selected
    ? p.articles.filter((a) => a.date.slice(0, 10) === dateKey(selected))
    : p.paginatedArticles;
  function pageUrl(page: number): string {
    const [path, query] = p.paginationBasePath.split("#")[0].split("?");
    const params = new URLSearchParams(query);
    params.set("page", String(page));
    return `${path}?${params}${p.paginationHash ? `#${p.paginationHash.replace(/^#/, "")}` : ""}`;
  }
  return (
    <section id={p.id ?? "calendar"}>
      <h2>{p.title}</h2>
      <button onClick={() => setMonth(new Date(year, index - 1, 1))}>Previous month</button>
      <span aria-live="polite">{month.toLocaleDateString(undefined, { month: "long", year: "numeric" })}</span>
      <button onClick={() => setMonth(new Date(year, index + 1, 1))}>Next month</button>
      <div className="grid grid-cols-7">
        {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => <span key={day}>{day}</span>)}
        {Array.from({ length: count }, (_, i) => {
          const date = new Date(year, index, i + 1);
          return <button key={i} style={i === 0 ? { gridColumnStart: date.getDay() + 1 } : undefined}
            aria-pressed={!!selected && dateKey(selected) === dateKey(date)}
            onClick={() => { setLocalDate(date); p.onDateSelect?.(date); }}>
            {i + 1}{p.articles.some((a) => a.date.startsWith(dateKey(date))) && " •"}
          </button>;
        })}
      </div>
      {visible.map((a) => <article key={a.slug}><h3>{a.title}</h3><p>{a.description}</p></article>)}
      {!selected && <nav aria-label="Article pagination">
        {p.currentPage > 1 && <Link to={pageUrl(p.currentPage - 1)}>Previous</Link>}
        <span>{p.currentPage} / {p.totalPages}</span>
        {p.currentPage < p.totalPages && <Link to={pageUrl(p.currentPage + 1)}>Next</Link>}
      </nav>}
    </section>
  );
}
```

## Semantics
`calendar`, `schedule`, `dates`, `events-calendar`, `date-picker`, `archive`, `timeline`

