# ArticleCompanyHighlightCTA

Prominent product/feature CTA with a bordered white container, text and actions beside an image. Use when more visual impact than ArticleCompanyCTA is needed.

File: `app/articles/ArticleCompanyHighlightCTA.tsx`

## Props

| Prop | Type | Default | Description |
|---|---|---|---|
| `title` | `string` | Required | CTA heading |
| `body` | `string` | Required | Description |
| `primaryButton` | `ButtonProps` | Required | Primary action |
| `image` | `string` | Required | Product/feature image URL |
| `label` | `string` | — | Small label above title |
| `secondaryButton` | `ButtonProps` | — | Secondary action |
| `note` | `string` | — | Small note |
| `id` | `string` | — | Section anchor ID |
| `className` | `string` | — | Additional classes |
| `imageAlt` | `string` | `title` | Meaningful image alternative |
| `imagePosition` | `"left" \| "right"` | `"right"` | Image placement |

`ButtonProps`: `text: string`, `href: string`, `variant?: "primary" | "secondary" | "outline"`.

## Semantic hints

`cta`, `highlight-cta`, `featured-cta`, `accent-cta`, `product-cta`, `demo-cta`, `showcase-cta`

## React Router implementation

Uses `Link` for navigation, not action buttons. Render within the application's router. Tailwind utilities below are component choices, not established project tokens.

```tsx
import { useId } from "react";
import { Link } from "react-router";

type ButtonProps = {
  text: string;
  href: string;
  variant?: "primary" | "secondary" | "outline";
};

type ArticleCompanyHighlightCTAProps = {
  title: string;
  body: string;
  primaryButton: ButtonProps;
  image: string;
  label?: string;
  secondaryButton?: ButtonProps;
  note?: string;
  id?: string;
  className?: string;
  imageAlt?: string;
  imagePosition?: "left" | "right";
};

export function ArticleCompanyHighlightCTA({
  title, body, primaryButton, image, label, secondaryButton,
  note, id, className = "", imageAlt = title, imagePosition = "right",
}: ArticleCompanyHighlightCTAProps) {
  const headingId = useId();

  return (
    <section
      id={id}
      aria-labelledby={headingId}
      className={`rounded-xl border bg-white p-6 text-black ${className}`}
    >
      <div className="grid items-center gap-6 md:grid-cols-2">
        <div>
          {label && <span className="text-xs font-bold uppercase text-blue-800">{label}</span>}
          <h2 id={headingId} className="text-3xl font-bold">{title}</h2>
          <p>{body}</p>
          <div className="my-4 flex flex-wrap items-center gap-3">
            {[primaryButton, secondaryButton].map((button, index) => button && (
              <Link
                key={index}
                to={button.href}
                className={`rounded border px-4 py-2 focus-visible:outline focus-visible:outline-2 ${
                  (button.variant ?? (index === 0 ? "primary" : "secondary")) === "primary"
                    ? "bg-black font-bold text-white"
                    : "bg-white text-black"
                }`}
              >
                {button.text}
              </Link>
            ))}
          </div>
          {note && <p className="text-sm">{note}</p>}
        </div>
        <div className={imagePosition === "left" ? "order-first" : ""}>
          <img src={image} alt={imageAlt} className="w-full rounded-lg object-contain" />
        </div>
      </div>
    </section>
  );
}

export function Example() {
  return (
    <ArticleCompanyHighlightCTA
      label="New Feature"
      title="AI-Powered Analytics"
      body="Explore real-time insights and predictions."
      primaryButton={{ text: "Start Free Trial", href: "/trial" }}
      secondaryButton={{ text: "Watch Demo", href: "/demo", variant: "outline" }}
      image="/images/analytics-dashboard.png"
      imageAlt="Analytics dashboard with real-time predictions"
      note="No credit card required"
    />
  );
}
